<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $items = Revayat_Companion_Member_Notes::review_queue( $args['user']->ID ); ?>
<?php if ( ! $items ) : ?><div class="rv-member-card rv-member-empty">یادداشتی برای بررسی شما وجود ندارد.</div><?php endif; ?>
<?php foreach ( $items as $note ) : ?><article class="rv-member-card"><h2><?php echo esc_html( $note->post_title ); ?></h2><div><?php echo wp_kses_post( wpautop( $note->post_content ) ); ?></div><form class="rv-member-form" data-rv-form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_note_review"><?php wp_nonce_field( 'rv_note_review', 'rv_nonce' ); ?><input type="hidden" name="post_id" value="<?php echo esc_attr( $note->ID ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( (int) get_post_meta( $note->ID, '_rv_note_version', true ) ); ?>"><label>نتیجه بررسی<select name="decision"><?php if ( current_user_can( 'edit_others_posts' ) ) : ?><option value="approved">تأیید و انتشار</option><?php endif; ?><option value="recommended">پیشنهاد انتشار به تحریریه</option><option value="changes_requested">درخواست اصلاح</option><option value="rejected">رد یادداشت</option></select></label><label>توضیح برای نویسنده<textarea name="reason" rows="3" maxlength="3000"></textarea></label><p data-form-status role="status" hidden></p><button class="rv-member-button">ثبت نتیجه</button></form></article><?php endforeach; ?>
